namespace CarRental.Web.Areas.Billing.Data;

public class Rate { public string Id { get; set; } = ""; public string Vehicle { get; set; } = ""; public string Unit { get; set; } = "NGAY"; public string Form { get; set; } = "NGAN_HAN"; public string Season { get; set; } = "MAC_DINH"; public bool Active { get; set; } = true; public decimal Amount { get; set; } public DateTime Start { get; set; } public DateTime End { get; set; } }
public class Surcharge { public string Id { get; set; } = ""; public string Name { get; set; } = ""; public string Calculation { get; set; } = "CO_DINH"; public string? Description { get; set; } public decimal Amount { get; set; } public bool Active { get; set; } = true; }
public class Invoice { public string Id { get; set; } = "H" + Guid.NewGuid().ToString("N")[..19]; public string Booking { get; set; } = ""; public string Creator { get; set; } = ""; public DateTime Created { get; set; } = DateTime.UtcNow; public decimal Rent { get; set; } public decimal Fees { get; set; } public decimal Discount { get; set; } public decimal Total { get; set; } public long Version { get; set; } }
public class InvoiceFee { public long Id { get; set; } public string Booking { get; set; } = ""; public string SurchargeId { get; set; } = ""; public string Name { get; set; } = ""; public string Calculation { get; set; } = ""; public decimal Quantity { get; set; } public decimal UnitPrice { get; set; } public decimal Amount { get; set; } public DateTime Created { get; set; } = DateTime.UtcNow; }
public class Payment { public string Id { get; set; } = "T" + Guid.NewGuid().ToString("N")[..29]; public string Booking { get; set; } = ""; public string Recorder { get; set; } = ""; public string Kind { get; set; } = ""; public string Method { get; set; } = ""; public decimal Amount { get; set; } public string? Reference { get; set; } public DateTime Created { get; set; } }
public class Complaint { public long Id { get; set; } public string InvoiceId { get; set; } = ""; public string Receiver { get; set; } = ""; public string? Resolver { get; set; } public string Channel { get; set; } = "TrucTiep"; public string Item { get; set; } = ""; public string Content { get; set; } = ""; public string Status { get; set; } = "ChoXuLy"; public string? Resolution { get; set; } public DateTime Created { get; set; } public DateTime? Resolved { get; set; } }
public class Promotion { [System.ComponentModel.DataAnnotations.Schema.NotMapped] public string? Revision {get;set;} public string Id { get; set; } = ""; public string Name { get; set; } = ""; public string Status { get; set; } = "SapApDung"; public DateTime Start { get; set; } public DateTime End { get; set; } public DateTime? ActualEnd { get; set; } public string? Description { get; set; } public string Kind { get; set; } = "PHAN_TRAM"; public decimal Value { get; set; } }
public class PromotionCondition { public long Id { get; set; } public string PromotionId { get; set; } = ""; public string Kind { get; set; } = "NHOM_KHACH"; public string? Group { get; set; } public string? Season { get; set; } public DateTime? Start { get; set; } public DateTime? End { get; set; } }
public class AppliedPromotion { public string Booking { get; set; } = ""; public string PromotionId { get; set; } = ""; public string Kind { get; set; } = ""; public decimal Value { get; set; } public decimal Discount { get; set; } public DateTime Applied { get; set; } }
// Read-only projection of the table owned by Bookings. EF never creates this table here.
public class BookingCost { public string Id { get; set; } = ""; public string RateId { get; set; } = ""; public DateTime Start { get; set; } public DateTime End { get; set; } public decimal UnitPrice { get; set; } public string Unit { get; set; } = ""; }
